CREATE COLUMN TABLE "TEST_AP"."OMRC" ("FirmCode" SMALLINT CS_INT NOT NULL , "FirmName" NVARCHAR(30) NOT NULL , "DataSource" NVARCHAR(1) DEFAULT 'N', "UserSign" SMALLINT CS_INT, PRIMARY KEY ("FirmCode")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "OMRC_GROUP_NAME" ON "TEST_AP"."OMRC" ( "FirmName" ASC )